int eval(Node* r) {
    if(!r) return 0;
    if(!r->l && !r->r) return r->v-'0';
    int lv=eval(r->l), rv=eval(r->r);
    if(r->v=='+') return lv+rv; if(r->v=='-') return lv-rv;
    if(r->v=='*') return lv*rv; return rv==0?0:lv/rv;
}
int main() {
    char s[105]; if(scanf("%s", s)!=1) return 0;
