        Node* nn=malloc(sizeof(Node)); nn->v=s[i]; nn->l=nn->r=NULL;
        if(isOp(s[i])) { nn->r=pop(); nn->l=pop(); push(nn); } else push(nn);
    }
    printf("%d\n", eval(stack[top])); return 0;
}

